import 'dart:async';
import 'dart:convert';
import 'dart:io';
import '../models/playlist_item.dart';

enum AIActionType {
  playChannel,
    searchContent,
      switchTab,
        openEPG,
          speakOnly,
          }

          class AICurationResult {
            final AIActionType action;
              final String speechResponse;
                final PlaylistItem? targetItem;
                  final String? searchQuery;
                    final String? targetTab; // 'live', 'movies', 'series'

                      AICurationResult({
                          required this.action,
                              required this.speechResponse,
                                  this.targetItem,
                                      this.searchQuery,
                                          this.targetTab,
                                            });
                                            }

                                            class AICuratorService {
                                              // Opcional: si tienes tu API Key de Gemini la puedes colocar aquí.
                                                // Si está vacía, el sistema usa el Cerebro Neuronal Local sin depender de internet.
                                                  static const String _geminiApiKey = ""; 

                                                    /// Limpia los nombres de canales y contenido M3U de manera profunda
                                                      static String cleanChannelName(String rawName) {
                                                          String cleaned = rawName;
                                                              final patterns = [
                                                                    RegExp(r'(\[|\().*?(\]|\))'), // Quita [ES], (FHD), [4K], etc.
                                                                          RegExp(r'^[a-z]{2,4}\s*[:|\-]\s*', caseSensitive: false), // Quita ES:, AR:, US:
                                                                                RegExp(r'\|\s*[a-z]{2,5}\s*\|', caseSensitive: false),
                                                                                      RegExp(r'\b(fhd|hd|sd|4k|2k|uhd|hevc|h265|1080p|720p|50fps|60fps|raw|vip|backup)\b', caseSensitive: false),
                                                                                            RegExp(r'\b(opcion\s*\d+|server\s*\d+|servidor\s*\d+)\b', caseSensitive: false),
                                                                                                  RegExp(r'\|.*$', caseSensitive: false),
                                                                                                      ];

                                                                                                          for (var pattern in patterns) {
                                                                                                                cleaned = cleaned.replaceAll(pattern, '');
                                                                                                                    }

                                                                                                                        return cleaned.trim().replaceAll(RegExp(r'\s+'), ' ');
                                                                                                                          }

                                                                                                                            /// Normalizador de categorías inteligentes
                                                                                                                              static String normalizeCategory(String rawCategory, String channelName) {
                                                                                                                                  final lower = '$rawCategory $channelName'.toLowerCase();
                                                                                                                                      if (lower.contains('sports') || lower.contains('deportes') || lower.contains('espn') || lower.contains('fox')) {
                                                                                                                                            return 'Deportes';
                                                                                                                                                } else if (lower.contains('news') || lower.contains('noticias') || lower.contains('cnn')) {
                                                                                                                                                      return 'Noticias';
                                                                                                                                                          } else if (lower.contains('movie') || lower.contains('cine') || lower.contains('hbo') || lower.contains('pelicula')) {
                                                                                                                                                                return 'Cine y Películas';
                                                                                                                                                                    } else if (lower.contains('kids') || lower.contains('infantil') || lower.contains('disney') || lower.contains('cartoon')) {
                                                                                                                                                                          return 'Infantil';
                                                                                                                                                                              } else if (lower.contains('serie') || lower.contains('series')) {
                                                                                                                                                                                    return 'Series';
                                                                                                                                                                                        }
                                                                                                                                                                                            return rawCategory.isNotEmpty ? rawCategory : 'Entretenimiento';
                                                                                                                                                                                              }

                                                                                                                                                                                                /// PROCESADOR INTELIGENTE DE COMANDOS DE VOZ
                                                                                                                                                                                                  static Future<AICurationResult> interpretVoiceCommand({
                                                                                                                                                                                                      required String userVoicePrompt,
                                                                                                                                                                                                          required List<PlaylistItem> availableItems,
                                                                                                                                                                                                              required String currentTab, // 'live', 'movies', 'series'
                                                                                                                                                                                                                }) async {
                                                                                                                                                                                                                    final prompt = userVoicePrompt.trim();
                                                                                                                                                                                                                        final lowerPrompt = prompt.toLowerCase();

                                                                                                                                                                                                                            if (prompt.isEmpty) {
                                                                                                                                                                                                                                  return AICurationResult(
                                                                                                                                                                                                                                          action: AIActionType.speakOnly,
                                                                                                                                                                                                                                                  speechResponse: "No logré escucharte. Intenta de nuevo.",
                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                // --- CAPA 1: DETECCIÓN DIRECTA ULTRA-RÁPIDA (0.01 segundos) ---

                                                                                                                                                                                                                                                                    // A) Guía de canales / EPG
                                                                                                                                                                                                                                                                        if (lowerPrompt.contains('guia') ||
                                                                                                                                                                                                                                                                                lowerPrompt.contains('epg') ||
                                                                                                                                                                                                                                                                                        lowerPrompt.contains('programacion') ||
                                                                                                                                                                                                                                                                                                lowerPrompt.contains('horario') ||
                                                                                                                                                                                                                                                                                                        lowerPrompt.contains('que estan dando')) {
                                                                                                                                                                                                                                                                                                              return AICurationResult(
                                                                                                                                                                                                                                                                                                                      action: AIActionType.openEPG,
                                                                                                                                                                                                                                                                                                                              speechResponse: "Abriendo la guía de programación.",
                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                            // B) Cambio a Películas
                                                                                                                                                                                                                                                                                                                                                if (lowerPrompt.contains('ir a peliculas') || lowerPrompt.contains('ver peliculas') || lowerPrompt == 'peliculas') {
                                                                                                                                                                                                                                                                                                                                                      return AICurationResult(
                                                                                                                                                                                                                                                                                                                                                              action: AIActionType.switchTab,
                                                                                                                                                                                                                                                                                                                                                                      targetTab: 'movies',
                                                                                                                                                                                                                                                                                                                                                                              speechResponse: "Cambiando a la sección de Películas.",
                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                            // C) Cambio a Series
                                                                                                                                                                                                                                                                                                                                                                                                if (lowerPrompt.contains('ir a series') || lowerPrompt.contains('ver series') || lowerPrompt == 'series') {
                                                                                                                                                                                                                                                                                                                                                                                                      return AICurationResult(
                                                                                                                                                                                                                                                                                                                                                                                                              action: AIActionType.switchTab,
                                                                                                                                                                                                                                                                                                                                                                                                                      targetTab: 'series',
                                                                                                                                                                                                                                                                                                                                                                                                                              speechResponse: "Cambiando a la sección de Series.",
                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                            // D) Cambio a En Vivo / Televisión
                                                                                                                                                                                                                                                                                                                                                                                                                                                if (lowerPrompt.contains('en vivo') || lowerPrompt.contains('television') || lowerPrompt.contains('canales')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                      return AICurationResult(
                                                                                                                                                                                                                                                                                                                                                                                                                                                              action: AIActionType.switchTab,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      targetTab: 'live',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              speechResponse: "Cambiando a Canales en Vivo.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // E) Búsqueda difusa de canales en la lista local
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                String cleanSearch = lowerPrompt
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .replaceAll(RegExp(r'^(pon|ponme|coloca|sintoniza|reproduce|cambia al|cambia a|quiero ver|vamos a ver)\s+'), '')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .replaceAll(RegExp(r'^(el canal|canal)\s+'), '')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            PlaylistItem? bestMatch;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double bestScore = 0.0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (final item in availableItems) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          final cleanName = cleanChannelName(item.name).toLowerCase();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Coincidencia exacta
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (cleanName == cleanSearch) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    bestMatch = item;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            bestScore = 1.0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Coincidencia contenida
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (cleanName.contains(cleanSearch) || cleanSearch.contains(cleanName)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              double score = 0.85;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (cleanName.startsWith(cleanSearch)) score = 0.95;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (score > bestScore) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        bestScore = score;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  bestMatch = item;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (bestMatch != null && bestScore >= 0.7) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return AICurationResult(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      action: AIActionType.playChannel,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              targetItem: bestMatch,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      speechResponse: "Sintonizando ${bestMatch.name}.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // --- CAPA 2: GEMINI AI CLOUD (Si hay API Key configurada) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (_geminiApiKey.isNotEmpty) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final geminiResult = await _queryGeminiAI(prompt, currentTab, availableItems);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (geminiResult != null) return geminiResult;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            print("Gemini API fallback: $e");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // --- CAPA 3: FILTRO INTELIGENTE DE CONTENIDO ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Si estás en Películas o Series y no es un canal, realizar búsqueda de contenido
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return AICurationResult(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        action: AIActionType.searchContent,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              searchQuery: cleanSearch,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    targetTab: currentTab,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          speechResponse: "Buscando $cleanSearch en $currentTab.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  /// Conexión HTTP nativa con Google Gemini REST API
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    static Future<AICurationResult?> _queryGeminiAI(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String prompt,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            String currentTab,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                List<PlaylistItem> items,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final sampleTitles = items.take(30).map((e) => cleanChannelName(e.name)).join(', ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          final systemPrompt = """
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Eres el asistente de voz IA de la app AMEYCAR TV.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          El usuario está actualmente en la pestaña: $currentTab.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          El usuario dice: "$prompt".
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Muestra de contenido disponible: [$sampleTitles].

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Responde ESTRICTAMENTE con un objeto JSON sin formato markdown:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "action": "play" | "search" | "epg" | "tab",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "target": "nombre exacto si aplica",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "tab": "live" | "movies" | "series",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "speech": "frase corta de confirmación estilo Alexa"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  """;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final client = HttpClient();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          final request = await client.postUrl(Uri.parse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=$_geminiApiKey',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        request.headers.set('Content-Type', 'application/json');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            request.add(utf8.encode(jsonEncode({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "contents": [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "parts": [{"text": systemPrompt}]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      })));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          final response = await request.close().timeout(const Duration(milliseconds: 1500));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (response.statusCode == 200) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    final responseBody = await response.transform(utf8.decoder).join();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          final json = jsonDecode(responseBody);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                final rawText = json['candidates'][0]['content']['parts'][0]['text'] as String;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final cleanJsonText = rawText.replaceAll('```json', '').replaceAll('```', '').trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            final data = jsonDecode(cleanJsonText);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  final actionStr = data['action'] ?? 'search';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        final speech = data['speech'] ?? "Entendido.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              final target = data['target'] ?? prompt;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    final tab = data['tab'] ?? currentTab;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (actionStr == 'epg') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return AICurationResult(action: AIActionType.openEPG, speechResponse: speech);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else if (actionStr == 'tab') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return AICurationResult(action: AIActionType.switchTab, targetTab: tab, speechResponse: speech);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return AICurationResult(action: AIActionType.searchContent, searchQuery: target, targetTab: tab, speechResponse: speech);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }